window.ZIX_MONSTRO_CODIGOS = {"schema":"zixlima-code-library-v1","version":"8.0.0","language":"pt-BR","updated":"2026-10-20","description":"Biblioteca integrada offline para APK MONSTRO IA 8; exemplos originais e pacote exclusivo 001. Nenhum código é executado automaticamente.","entries":[{"id":"zix-001","category":"Termux / Linux","language":"Bash","title":"Instalar dependências no Termux","summary":"Atualiza pacotes e instala ferramentas de desenvolvimento no Android.","level":"Intermediário","tags":["android","pkg","setup"],"filename":"exemplo.sh","code":"#!/usr/bin/env bash\nset -euo pipefail\nif [[ \"${PREFIX:-}\" != *com.termux* ]]; then echo \"Abra no Termux.\"; exit 1; fi\npkg update -y\npkg install -y python git nodejs jq curl\npython --version && node --version && git --version\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-002","category":"Termux / Linux","language":"Bash","title":"Backup com data e hora","summary":"Gera um backup compactado de uma pasta sem remover o original.","level":"Intermediário","tags":["backup","tar","segurança"],"filename":"exemplo.sh","code":"#!/usr/bin/env bash\nset -euo pipefail\norigem=\"${1:?Informe uma pasta}\"; destino=\"${2:?Informe destino}\"\n[[ -d \"$origem\" ]] || { echo \"Origem inexistente\"; exit 1; }\nmkdir -p \"$destino\"\narquivo=\"$destino/backup-$(date +%Y%m%d-%H%M%S).tar.gz\"\ntar -czf \"$arquivo\" -C \"$(dirname \"$origem\")\" \"$(basename \"$origem\")\"\necho \"Backup criado: $arquivo\"\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-003","category":"Termux / Linux","language":"Bash","title":"Validação de projeto antes de publicar","summary":"Confere espaços inválidos, testes e build antes de um possível envio ao GitHub.","level":"Intermediário","tags":["git","npm","testes"],"filename":"exemplo.sh","code":"#!/usr/bin/env bash\nset -euo pipefail\ncd \"${1:-.}\"\ngit diff --check\nif [[ -f package.json ]]; then\n  npm test --if-present\n  npm run build --if-present\nfi\ngit status --short\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-004","category":"Termux / Linux","language":"Bash","title":"Git push sem reescrever histórico","summary":"Sincronização conservadora: não apaga modificações nem usa push forçado.","level":"Intermediário","tags":["github","sincronização"],"filename":"exemplo.sh","code":"#!/usr/bin/env bash\nset -euo pipefail\ncd \"${1:?Informe o repositório}\"\n[[ -z \"$(git status --porcelain)\" ]] || { echo \"Há alterações locais; revise antes.\"; exit 1; }\ngit pull --ff-only origin main\necho \"Sincronizado. Faça commits intencionalmente antes do git push.\"\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-005","category":"Termux / Linux","language":"Bash","title":"Servidor HTTP local para projeto","summary":"Publica arquivos locais só para o próprio dispositivo.","level":"Intermediário","tags":["python","html","localhost"],"filename":"exemplo.sh","code":"#!/usr/bin/env bash\nset -euo pipefail\ncd \"${1:-.}\"\npython -m http.server 8765 --bind 127.0.0.1\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-006","category":"Termux / Linux","language":"Bash","title":"Conferir tamanho de arquivos","summary":"Encontra arquivos grandes antes de fazer upload ou gerar APK.","level":"Intermediário","tags":["otimização","imagens"],"filename":"exemplo.sh","code":"#!/usr/bin/env bash\nset -euo pipefail\npasta=\"${1:-.}\"\nfind \"$pasta\" -type f -size +5M -print\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-007","category":"Termux / Linux","language":"Bash","title":"Checar sintaxe de JavaScript com Node","summary":"Encontra erros sintáticos comuns antes de executar o código.","level":"Intermediário","tags":["node","javascript","verificação"],"filename":"exemplo.sh","code":"#!/usr/bin/env bash\nset -euo pipefail\narquivo=\"${1:?Informe arquivo .js}\"\nnode --check \"$arquivo\"\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-008","category":"Termux / Linux","language":"Bash","title":"Checar projeto Python","summary":"Compila código Python para detectar erros sintáticos sem rodar funções.","level":"Intermediário","tags":["python","teste"],"filename":"exemplo.sh","code":"#!/usr/bin/env bash\nset -euo pipefail\npasta=\"${1:-.}\"\npython -m compileall -q \"$pasta\"\necho \"Sintaxe Python verificada.\"\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-009","category":"Termux / Linux","language":"Bash","title":"Instalar FFmpeg no Termux","summary":"Prepara o Android para processar áudio e vídeo.","level":"Intermediário","tags":["video","multimídia"],"filename":"exemplo.sh","code":"#!/usr/bin/env bash\nset -euo pipefail\npkg install -y ffmpeg\nffmpeg -version | head -n 1\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-010","category":"Termux / Linux","language":"Bash","title":"Ver disponibilidade de porta","summary":"Ajuda a resolver o erro de porta ocupada ao iniciar um servidor.","level":"Intermediário","tags":["servidor","rede"],"filename":"exemplo.sh","code":"#!/usr/bin/env bash\nset -euo pipefail\npython - <<'CHECK'\nimport socket\nwith socket.socket() as s:\n    try: s.bind(('127.0.0.1', 8765)); print('Porta 8765 livre')\n    except OSError: print('Porta 8765 ocupada')\nCHECK\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-011","category":"Termux / Linux","language":"Bash","title":"Script de instalação com cópia segura","summary":"Atualiza um arquivo e salva a versão anterior se existir.","level":"Intermediário","tags":["deploy","backup"],"filename":"exemplo.sh","code":"#!/usr/bin/env bash\nset -euo pipefail\norigem=\"${1:?Arquivo de origem}\"; destino=\"${2:?Arquivo de destino}\"\n[[ -f \"$origem\" ]] || { echo \"Origem não encontrada\"; exit 1; }\nif [[ -e \"$destino\" ]]; then cp -p -- \"$destino\" \"$destino.bak.$(date +%s)\"; fi\ninstall -m 0644 -- \"$origem\" \"$destino\"\necho \"Atualizado: $destino\"\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-012","category":"Termux / Linux","language":"Git","title":"Histórico e recuperação sem perda","summary":"Inspeciona mudanças e versões sem executar reset destrutivo.","level":"Intermediário","tags":["git","auditoria"],"filename":"git-comandos.sh","code":"git status --short\ngit log --oneline -8\ngit diff --stat\ngit diff --check\n# Para retornar a um arquivo anterior, veja primeiro:\n# git show <commit>:caminho/do/arquivo\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-013","category":"Python e automação","language":"Python","title":"CLI com argparse","summary":"Crie utilitários de linha de comando com parâmetros e modo de simulação.","level":"Intermediário","tags":["cli","arquitetura"],"filename":"exemplo.py","code":"import argparse\np=argparse.ArgumentParser(description='Ferramenta de manutenção')\np.add_argument('projeto')\np.add_argument('--seco', action='store_true', help='Simular sem alterar')\na=p.parse_args()\nprint({'projeto':a.projeto, 'simulacao':a.seco})\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-014","category":"Python e automação","language":"Python","title":"Ler e salvar JSON com segurança","summary":"Usa escrita temporária para reduzir risco de dados JSON incompletos.","level":"Intermediário","tags":["json","backup"],"filename":"exemplo.py","code":"import json\nfrom pathlib import Path\narquivo=Path('dados.json')\ndados=json.loads(arquivo.read_text(encoding='utf-8')) if arquivo.exists() else {}\ndados['versao']=dados.get('versao',0)+1\ntmp=arquivo.with_suffix('.tmp')\ntmp.write_text(json.dumps(dados,ensure_ascii=False,indent=2),encoding='utf-8')\ntmp.replace(arquivo)\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-015","category":"Python e automação","language":"Python","title":"SQLite local com parâmetros","summary":"Banco SQLite real com consultas parametrizadas para evitar injeção SQL.","level":"Intermediário","tags":["sqlite","database","segurança"],"filename":"exemplo.py","code":"import sqlite3\nwith sqlite3.connect('monstro.db') as db:\n    db.execute('CREATE TABLE IF NOT EXISTS projetos (id INTEGER PRIMARY KEY, nome TEXT NOT NULL)')\n    db.execute('INSERT INTO projetos(nome) VALUES (?)', ('ZixLima',))\n    print(db.execute('SELECT id,nome FROM projetos WHERE nome=?',('ZixLima',)).fetchall())\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-016","category":"Python e automação","language":"Python","title":"Requisição HTTP com timeout","summary":"Consulta API pública sem dependências externas, com tempo máximo.","level":"Intermediário","tags":["api","http","internet"],"filename":"exemplo.py","code":"import json, urllib.request\nreq=urllib.request.Request('https://api.github.com',headers={'User-Agent':'MonstroIA-Exemplo'})\nwith urllib.request.urlopen(req,timeout=10) as resposta:\n    dados=json.load(resposta)\nprint(dados.get('current_user_url'))\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-017","category":"Python e automação","language":"Python","title":"ThreadPool para tarefas I/O","summary":"Executa tarefas de rede concorrentes com número limitado de threads.","level":"Intermediário","tags":["concorrência","rede"],"filename":"exemplo.py","code":"from concurrent.futures import ThreadPoolExecutor\nfrom urllib.request import urlopen\nurls=['https://example.org','https://www.python.org']\ndef tamanho(url):\n    with urlopen(url,timeout=8) as r: return url, len(r.read(200_000))\nwith ThreadPoolExecutor(max_workers=3) as pool:\n    for resultado in pool.map(tamanho,urls): print(resultado)\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-018","category":"Python e automação","language":"Python","title":"Asyncio para tarefas concorrentes","summary":"Modelo simples de concorrência assíncrona em Python.","level":"Intermediário","tags":["async","arquitetura"],"filename":"exemplo.py","code":"import asyncio\nasync def tarefa(n):\n    await asyncio.sleep(.2)\n    return {'id':n,'ok':True}\nasync def main():\n    print(await asyncio.gather(*(tarefa(n) for n in range(5))))\nasyncio.run(main())\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-019","category":"Python e automação","language":"Python","title":"Logging rotativo","summary":"Registra diagnósticos em arquivo com rotação para não encher o armazenamento.","level":"Intermediário","tags":["logs","observabilidade"],"filename":"exemplo.py","code":"import logging\nfrom logging.handlers import RotatingFileHandler\nlogger=logging.getLogger('monstro');logger.setLevel(logging.INFO)\nh=RotatingFileHandler('sistema.log',maxBytes=300_000,backupCount=3,encoding='utf-8')\nh.setFormatter(logging.Formatter('%(asctime)s %(levelname)s %(message)s'))\nlogger.addHandler(h)\nlogger.info('Aplicação iniciada')\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-020","category":"Python e automação","language":"Python","title":"Testes unitários unittest","summary":"Testes automatizados para regras de negócio.","level":"Intermediário","tags":["tests","preço"],"filename":"exemplo.py","code":"import unittest\ndef preco_final(preco,desconto):\n    if not 0<=desconto<=100: raise ValueError('Desconto inválido')\n    return round(preco*(1-desconto/100),2)\nclass PrecoTest(unittest.TestCase):\n    def test_desconto(self): self.assertEqual(preco_final(100,20),80)\n    def test_limite(self):\n        with self.assertRaises(ValueError): preco_final(100,110)\nif __name__=='__main__':unittest.main()\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-021","category":"Python e automação","language":"Python","title":"Hash SHA-256 de arquivo","summary":"Calcula a impressão digital de um arquivo sem carregá-lo inteiro na RAM.","level":"Intermediário","tags":["integridade","segurança"],"filename":"exemplo.py","code":"import hashlib\nfrom pathlib import Path\np=Path('arquivo.bin');sha=hashlib.sha256()\nwith p.open('rb') as f:\n    for bloco in iter(lambda:f.read(1024*1024),b''):sha.update(bloco)\nprint(sha.hexdigest())\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-022","category":"Python e automação","language":"Python","title":"Remover duplicados mantendo ordem","summary":"Técnica eficiente de deduplicação.","level":"Intermediário","tags":["algoritmos","coleções"],"filename":"exemplo.py","code":"def unicos(itens):\n    vistos=set();saida=[]\n    for item in itens:\n        if item not in vistos:\n            vistos.add(item);saida.append(item)\n    return saida\nprint(unicos(['A','B','A','C']))\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-023","category":"Python e automação","language":"Python","title":"CSV com codificação UTF-8","summary":"Gera relatórios em CSV compatíveis com diversos programas.","level":"Intermediário","tags":["relatorios","dados"],"filename":"exemplo.py","code":"import csv\nwith open('relatorio.csv','w',newline='',encoding='utf-8-sig') as f:\n    w=csv.DictWriter(f,fieldnames=['id','nome','valor'])\n    w.writeheader();w.writerow({'id':1,'nome':'Anúncio','valor':99.90})\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-024","category":"Python e automação","language":"Python","title":"Fila em memória thread-safe","summary":"Fila simples para separar a solicitação de trabalho do processamento.","level":"Intermediário","tags":["filas","arquitetura"],"filename":"exemplo.py","code":"from queue import Queue\nfila=Queue(maxsize=100)\nfila.put({'tarefa':'gerar_preview','id':'exemplo'})\nitem=fila.get(timeout=1)\ntry: print('Processando:',item)\nfinally: fila.task_done()\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-025","category":"Python e automação","language":"Python","title":"Padrão de retry com backoff","summary":"Tenta novamente falhas transitórias de rede sem sobrecarregar o serviço.","level":"Intermediário","tags":["resiliência","api"],"filename":"exemplo.py","code":"import time,random\nfrom urllib.error import URLError\nfrom urllib.request import urlopen\nfor tentativa in range(4):\n    try:\n        with urlopen('https://example.org',timeout=7) as r:\n            print(r.status);break\n    except URLError:\n        if tentativa==3:raise\n        time.sleep(min(8,2**tentativa)+random.random())\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-026","category":"Python e automação","language":"Python","title":"Servidor HTTP local só para o aparelho","summary":"Servidor para desenvolvimento que não abre portas à rede externa.","level":"Intermediário","tags":["local","servidor"],"filename":"exemplo.py","code":"from http.server import ThreadingHTTPServer, SimpleHTTPRequestHandler\nservidor=ThreadingHTTPServer(('127.0.0.1',8765),SimpleHTTPRequestHandler)\nprint('Abra http://127.0.0.1:8765')\ntry: servidor.serve_forever()\nexcept KeyboardInterrupt: servidor.server_close()\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-027","category":"JavaScript e Web","language":"JavaScript","title":"Fetch com AbortController","summary":"Acesso assíncrono com limite de espera e validação HTTP.","level":"Intermediário","tags":["http","async"],"filename":"exemplo.js","code":"async function buscar(url){\n  const controller=new AbortController();\n  const timer=setTimeout(()=>controller.abort(),8000);\n  try{\n    const response=await fetch(url,{signal:controller.signal});\n    if(!response.ok)throw Error(`HTTP ${response.status}`);\n    return await response.json();\n  }finally{clearTimeout(timer)}\n}\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-028","category":"JavaScript e Web","language":"JavaScript","title":"Debounce na busca","summary":"Evita pesquisas repetidas a cada tecla pressionada.","level":"Intermediário","tags":["performance","busca"],"filename":"exemplo.js","code":"function debounce(fn,tempo=300){\n  let temporizador;\n  return (...args)=>{clearTimeout(temporizador);temporizador=setTimeout(()=>fn(...args),tempo)};\n}\nconst buscar=debounce(termo=>console.log('Buscando',termo),350);\n// campo.addEventListener('input',event=>buscar(event.target.value));\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-029","category":"JavaScript e Web","language":"JavaScript","title":"Persistência local com tratamento","summary":"Armazenamento de preferências leves no navegador com fallback.","level":"Intermediário","tags":["localstorage","offline"],"filename":"exemplo.js","code":"function guardar(chave,valor){try{localStorage.setItem(chave,JSON.stringify(valor));return true}catch{return false}}\nfunction ler(chave,padrao=null){try{const v=localStorage.getItem(chave);return v?JSON.parse(v):padrao}catch{return padrao}}\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-030","category":"JavaScript e Web","language":"JavaScript","title":"Copiar texto com fallback","summary":"Copia código de maneira compatível com navegadores modernos e alguns legados.","level":"Intermediário","tags":["clipboard","interface"],"filename":"exemplo.js","code":"async function copiar(texto){\n  if(navigator.clipboard && window.isSecureContext){await navigator.clipboard.writeText(texto);return}\n  const area=document.createElement('textarea');area.value=texto;document.body.append(area);area.select();\n  try{document.execCommand('copy')}finally{area.remove()}\n}\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-031","category":"JavaScript e Web","language":"JavaScript","title":"Criar download sem servidor","summary":"Exporta TXT, JSON e códigos do próprio navegador.","level":"Intermediário","tags":["exportar","blob"],"filename":"exemplo.js","code":"function baixar(nome,conteudo,tipo='text/plain'){\n  const url=URL.createObjectURL(new Blob([conteudo],{type:tipo}));\n  const link=document.createElement('a');link.href=url;link.download=nome;link.click();\n  setTimeout(()=>URL.revokeObjectURL(url),3000);\n}\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-032","category":"JavaScript e Web","language":"JavaScript","title":"Formulário com validação segura","summary":"Usa HTML5 para validar entradas sem expor senhas no console.","level":"Intermediário","tags":["formularios","segurança"],"filename":"exemplo.js","code":"const form=document.querySelector('form');\nform.addEventListener('submit',event=>{\n  event.preventDefault();\n  if(!form.reportValidity())return;\n  const dados=Object.fromEntries(new FormData(form));\n  console.log('Campos preenchidos:',Object.keys(dados)); // não imprimir senhas\n});\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-033","category":"JavaScript e Web","language":"JavaScript","title":"Escape de HTML usando textContent","summary":"Evita injeção de marcação quando exibe dados fornecidos por usuários.","level":"Intermediário","tags":["xss","segurança"],"filename":"exemplo.js","code":"function mensagemSegura(conteudo,alvo){\n  const p=document.createElement('p');p.textContent=String(conteudo);\n  alvo.replaceChildren(p);\n}\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-034","category":"JavaScript e Web","language":"JavaScript","title":"Upload com tamanho máximo","summary":"Valida tamanho no cliente; servidor ainda deve revalidar.","level":"Intermediário","tags":["upload","segurança"],"filename":"exemplo.js","code":"function validarArquivo(file,maxMB=3){\n  if(!file)throw Error('Selecione um arquivo');\n  if(file.size>maxMB*1024*1024)throw Error('Arquivo muito grande');\n  return {nome:file.name,tamanho:file.size,tipo:file.type};\n}\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-035","category":"JavaScript e Web","language":"JavaScript","title":"IndexDB base local simples","summary":"Esqueleto de banco local IndexedDB que suporta mais dados que localStorage.","level":"Intermediário","tags":["indexeddb","offline"],"filename":"exemplo.js","code":"function abrirDb(){return new Promise((ok,falha)=>{\n  const req=indexedDB.open('MonstroLocal',1);\n  req.onupgradeneeded=()=>req.result.createObjectStore('notas',{keyPath:'id'});\n  req.onsuccess=()=>ok(req.result);req.onerror=()=>falha(req.error);\n})}\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-036","category":"JavaScript e Web","language":"JavaScript","title":"API REST Express com limite JSON","summary":"API Node/Express mínima que escuta apenas localhost.","level":"Intermediário","tags":["node","api"],"filename":"exemplo.js","code":"import express from 'express';\nconst app=express();app.disable('x-powered-by');app.use(express.json({limit:'50kb'}));\napp.get('/api/health',(_req,res)=>res.json({ok:true}));\napp.listen(3000,'127.0.0.1',()=>console.log('http://127.0.0.1:3000'));\n// Instale: npm install express\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-037","category":"JavaScript e Web","language":"JavaScript","title":"Módulo ESM com funções puras","summary":"Separa cálculo de interface, facilitando testes e reuso.","level":"Intermediário","tags":["arquitetura","esm"],"filename":"exemplo.js","code":"export function calcularDesconto(preco,taxa){\n  if(!Number.isFinite(preco)||taxa<0||taxa>100)throw Error('Entrada inválida');\n  return Math.round(preco*(1-taxa/100)*100)/100;\n}\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-038","category":"Aplicativos e interface","language":"TypeScript","title":"Tipo forte de anúncio","summary":"Representa entidades de domínio com checagem estática de tipos.","level":"Intermediário","tags":["tipagem","anuncios"],"filename":"exemplo.ts","code":"type Estado='pending'|'approved'|'rejected';\ninterface Anuncio{id:string;titulo:string;preco:number;estado:Estado}\nconst publicado=(a:Anuncio)=>a.estado==='approved';\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-039","category":"Aplicativos e interface","language":"TypeScript","title":"Resultado tipado sem lançar exceção","summary":"Retorno discriminado para tratar sucesso e falha sem ambiguidades.","level":"Intermediário","tags":["typescript","validacao"],"filename":"exemplo.ts","code":"type Resultado<T>={ok:true;dados:T}|{ok:false;erro:string};\nfunction validarCep(cep:string):Resultado<string>{\n  const digitos=cep.replace(/\\D/g,'');\n  return /^\\d{8}$/.test(digitos)?{ok:true,dados:digitos}:{ok:false,erro:'CEP inválido'};\n}\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-040","category":"Aplicativos e interface","language":"HTML","title":"HTML semântico com formulário acessível","summary":"Estrutura responsiva e acessível com etiquetas conectadas aos inputs.","level":"Intermediário","tags":["html","acessibilidade"],"filename":"index.html","code":"<!doctype html><html lang=\"pt-BR\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><title>Cadastro</title></head><body>\n<main><h1>Novo anúncio</h1><form><label for=\"titulo\">Título</label><input id=\"titulo\" name=\"titulo\" required minlength=\"8\"><button type=\"submit\">Enviar</button></form></main>\n</body></html>\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-041","category":"Aplicativos e interface","language":"CSS","title":"Grid responsivo com mínimo seguro","summary":"Layout que adapta cartões sem estourar a tela do celular.","level":"Intermediário","tags":["responsive","desktop","mobile"],"filename":"estilo.css","code":".cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,260px),1fr));gap:16px}\n.card{border:1px solid #ddd;border-radius:12px;padding:16px;min-width:0}\n.card img{max-width:100%;height:auto;display:block}\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-042","category":"Aplicativos e interface","language":"CSS","title":"Modo escuro respeitando sistema","summary":"Tema automático claro/escuro baseado na preferência do usuário.","level":"Intermediário","tags":["tema","acessibilidade"],"filename":"estilo.css","code":":root{color-scheme:light dark;--bg:#fff;--fg:#171717}\n@media(prefers-color-scheme:dark){:root{--bg:#111;--fg:#f3f3f3}}\nbody{background:var(--bg);color:var(--fg)}\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-043","category":"Aplicativos e interface","language":"JavaScript","title":"PWA verificar instalação","summary":"Mostra instalação quando o navegador disponibiliza o evento PWA.","level":"Intermediário","tags":["pwa","android"],"filename":"exemplo.js","code":"window.addEventListener('beforeinstallprompt',event=>{\n  event.preventDefault();\n  const instalar=document.getElementById('instalar');\n  instalar.hidden=false;\n  instalar.onclick=async()=>{await event.prompt();instalar.hidden=true};\n});\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-044","category":"Aplicativos e interface","language":"JSON","title":"Manifest PWA","summary":"Manifest do aplicativo instalável. Adicione ícones reais e HTTPS para PWA.","level":"Intermediário","tags":["pwa","manifest"],"filename":"config.json","code":"{\"name\":\"Meu Aplicativo\",\"short_name\":\"MeuApp\",\"start_url\":\"./\",\"display\":\"standalone\",\"background_color\":\"#101820\",\"theme_color\":\"#127963\",\"icons\":[{\"src\":\"icone-192.png\",\"sizes\":\"192x192\",\"type\":\"image/png\"}]}\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-045","category":"Aplicativos e interface","language":"Kotlin","title":"Activity Android WebView local","summary":"Modelo didático de WebView; para produção prefira WebViewAssetLoader e controle de navegação.","level":"Intermediário","tags":["android","apk"],"filename":"MainActivity.kt","code":"// Exemplo de Activity para projeto Android Studio com WebView.\nclass MainActivity : android.app.Activity() {\n  override fun onCreate(savedInstanceState: android.os.Bundle?) {\n    super.onCreate(savedInstanceState)\n    val web=android.webkit.WebView(this)\n    web.settings.javaScriptEnabled=true // Apenas para conteúdo local confiável\n    setContentView(web)\n    web.loadUrl(\"file:///android_asset/index.html\")\n  }\n}\n","caution":"Exemplo didático: não usar para navegar em conteúdo não confiável. APK final requer Android SDK e configuração Gradle."},{"id":"zix-046","category":"Aplicativos e interface","language":"PowerShell","title":"Servidor local pelo Python no Windows","summary":"Inicia ambiente web local no Windows sem expor a porta à rede.","level":"Intermediário","tags":["windows","localhost"],"filename":"exemplo.ps1","code":"$ErrorActionPreference='Stop'\nSet-Location $PSScriptRoot\npy -3 -m http.server 8765 --bind 127.0.0.1\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-047","category":"Aplicativos e interface","language":"Java","title":"Leitura UTF-8 de arquivo","summary":"Usa APIs modernas do Java para processar texto.","level":"Intermediário","tags":["java","arquivos"],"filename":"Main.java","code":"import java.nio.file.*;\nimport java.nio.charset.StandardCharsets;\npublic class Main {\n  public static void main(String[] args) throws Exception {\n    System.out.println(Files.readString(Path.of(\"dados.txt\"),StandardCharsets.UTF_8));\n  }\n}\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-048","category":"Bancos e Supabase","language":"SQL","title":"Criar tabela de anúncios","summary":"Exemplo isolado de tabela PostgreSQL para exercícios, sem alterar a tabela real listings.","level":"Intermediário","tags":["postgres","schema"],"filename":"consulta.sql","code":"CREATE TABLE IF NOT EXISTS public.anuncios_exemplo (\n id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n titulo text NOT NULL CHECK (length(titulo) BETWEEN 8 AND 100),\n preco numeric(12,2) NOT NULL CHECK(preco>=0),\n created_at timestamptz NOT NULL DEFAULT now()\n);\n","caution":"Execute em ambiente de teste. Não aplique à produção sem revisão e backup."},{"id":"zix-049","category":"Bancos e Supabase","language":"SQL","title":"Índice para filtros frequentes","summary":"Índice para acelerar listagens ordenadas por data.","level":"Intermediário","tags":["sql","performance"],"filename":"consulta.sql","code":"CREATE INDEX IF NOT EXISTS idx_anuncios_exemplo_criado\nON public.anuncios_exemplo(created_at DESC);\n","caution":"Exemplo usa tabela fictícia anuncios_exemplo. Avalie espaço e plano de consulta antes de criar índices em produção."},{"id":"zix-050","category":"Bancos e Supabase","language":"SQL","title":"Consulta paginada com parâmetros","summary":"Modelo parametrizado com limite por página.","level":"Intermediário","tags":["sql","paginação"],"filename":"consulta.sql","code":"SELECT id,titulo,preco,created_at\nFROM public.anuncios_exemplo\nWHERE preco >= $1\nORDER BY created_at DESC\nLIMIT LEAST($2,100) OFFSET $3;\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-051","category":"Bancos e Supabase","language":"SQL","title":"Transação com rollback em erro","summary":"Mostra como estudar uma alteração SQL sem persistir mudanças.","level":"Intermediário","tags":["postgres","transação"],"filename":"consulta.sql","code":"BEGIN;\nUPDATE public.anuncios_exemplo SET preco=preco*0.95 WHERE id=$1;\n-- Se conferiu os dados, use COMMIT; caso contrário ROLLBACK.\nROLLBACK;\n","caution":"A cláusula usa um parâmetro $1 e termina com ROLLBACK intencional."},{"id":"zix-052","category":"Bancos e Supabase","language":"SQL","title":"Ativar Row Level Security","summary":"Ilustra ativação de RLS: sem políticas adequadas, clientes não acessam os registros.","level":"Intermediário","tags":["rls","supabase","seguranca"],"filename":"consulta.sql","code":"ALTER TABLE public.anuncios_exemplo ENABLE ROW LEVEL SECURITY;\nCREATE POLICY \"leitura de exemplos\" ON public.anuncios_exemplo\nFOR SELECT TO authenticated USING (true);\n","caution":"Não aplique a tabelas existentes sem mapear todas as operações e políticas atuais."},{"id":"zix-053","category":"Bancos e Supabase","language":"SQL","title":"Política dono do registro","summary":"Modelo de controle de acesso ao registro do próprio usuário.","level":"Intermediário","tags":["auth","rls"],"filename":"consulta.sql","code":"-- Exige coluna owner_id uuid corretamente preenchida.\nCREATE POLICY \"edita somente seus anuncios\" ON public.anuncios_exemplo\nFOR UPDATE TO authenticated\nUSING (owner_id = (SELECT auth.uid()))\nWITH CHECK (owner_id = (SELECT auth.uid()));\n","caution":"Exemplo depende da coluna owner_id, que não está no exemplo básico. Não execute sem preparar esquema e outras políticas."},{"id":"zix-054","category":"Bancos e Supabase","language":"SQL","title":"Contar status com GROUP BY","summary":"Relatório somente leitura para acompanhar moderação de anúncios.","level":"Intermediário","tags":["zixlima","relatorios","sql"],"filename":"consulta.sql","code":"SELECT status, COUNT(*) AS total\nFROM public.listings\nGROUP BY status\nORDER BY total DESC;\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-055","category":"Bancos e Supabase","language":"SQL","title":"Detectar registros duplicados","summary":"Localiza nomes repetidos sem apagar registros.","level":"Intermediário","tags":["sql","auditoria"],"filename":"consulta.sql","code":"SELECT lower(trim(titulo)) AS titulo_normalizado, COUNT(*) AS ocorrencias\nFROM public.anuncios_exemplo\nGROUP BY lower(trim(titulo))\nHAVING COUNT(*)>1;\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-056","category":"Bancos e Supabase","language":"JavaScript","title":"Criar cliente Supabase no front","summary":"Consulta Supabase por SDK com chave pública e RLS corretamente configurado.","level":"Intermediário","tags":["supabase","api"],"filename":"exemplo.js","code":"import { createClient } from '@supabase/supabase-js';\nconst db=createClient('https://SEU_PROJETO.supabase.co','SUA_CHAVE_PUBLICA_ANON');\nconst {data,error}=await db.from('anuncios_exemplo').select('id,titulo').limit(10);\nif(error)throw error;console.log(data);\n","caution":"Nunca use service_role no navegador. Configure RLS antes de compartilhar dados."},{"id":"zix-057","category":"Bancos e Supabase","language":"JavaScript","title":"Supabase: autenticação por e-mail","summary":"Cadastro básico com fluxo de confirmação conforme configuração do Supabase.","level":"Intermediário","tags":["login","email"],"filename":"exemplo.js","code":"const {data,error}=await db.auth.signUp({email, password, options:{emailRedirectTo:'https://seusite.exemplo/confirmar.html'}});\nif(error)throw error;\n// Se a confirmação estiver ativada, informe ao usuário para verificar o e-mail.\n","caution":"Substitua URL e trate limite de tentativas, política de senhas e preferências de autenticação."},{"id":"zix-058","category":"Bancos e Supabase","language":"JavaScript","title":"Consulta de anúncio pelo UUID","summary":"Busca um anúncio no banco, respeitando as políticas RLS.","level":"Intermediário","tags":["zixlima","anuncio","supabase"],"filename":"exemplo.js","code":"const id='00000000-0000-4000-8000-000000000000';\nconst {data,error}=await db.from('listings').select('id,title,status').eq('id',id).maybeSingle();\nif(error)throw error;console.log(data);\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-059","category":"Bancos e Supabase","language":"SQL","title":"Auditoria de aceites jurídicos (exemplo)","summary":"Modelo introdutório de trilha de auditoria para consentimento.","level":"Intermediário","tags":["lgpd","rls","supabase"],"filename":"consulta.sql","code":"CREATE TABLE public.aceites_exemplo (\n id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,\n user_id uuid NOT NULL REFERENCES auth.users(id),\n versao_termos text NOT NULL,\n aceite_em timestamptz NOT NULL DEFAULT now()\n);\nALTER TABLE public.aceites_exemplo ENABLE ROW LEVEL SECURITY;\n-- Nenhuma política para anônimos: configure gravação autenticada e auditoria no backend.\n","caution":"Esquema demonstrativo incompleto: antes de produção, definir base legal, retenção, políticas e registro confiável no backend."},{"id":"zix-060","category":"Segurança e testes","language":"Python","title":"Senhas com scrypt e sal aleatório","summary":"Exemplo didático de derivação criptográfica; não armazene senhas em texto puro.","level":"Intermediário","tags":["hash","autenticacao"],"filename":"exemplo.py","code":"import os,hashlib,hmac\nsenha='exemplo_de_teste'\nsal=os.urandom(16)\nderivado=hashlib.scrypt(senha.encode(),salt=sal,n=2**14,r=8,p=1)\nvalidar=hmac.compare_digest(derivado,hashlib.scrypt(senha.encode(),salt=sal,n=2**14,r=8,p=1))\nprint(validar)\n","caution":"Para autenticação real, use Supabase Auth ou biblioteca confiável com parâmetros atualizados, não um sistema caseiro."},{"id":"zix-061","category":"Segurança e testes","language":"Python","title":"Validar caminho dentro da pasta permitida","summary":"Evita acesso a caminhos relativos fora de diretório permitido (Python 3.9+).","level":"Intermediário","tags":["arquivos","seguranca"],"filename":"exemplo.py","code":"from pathlib import Path\nRAIZ=Path('arquivos').resolve()\ndef caminho_seguro(nome):\n    destino=(RAIZ/nome).resolve()\n    if not destino.is_relative_to(RAIZ):raise ValueError('Caminho fora da pasta')\n    return destino\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-062","category":"Segurança e testes","language":"JavaScript","title":"Normalizar CEP brasileiro","summary":"Valida formato de CEP antes de consultar serviço externo.","level":"Intermediário","tags":["brasil","viaCEP"],"filename":"exemplo.js","code":"function cepValido(texto){\n  const cep=String(texto).replace(/\\D/g,'');\n  return /^\\d{8}$/.test(cep)?cep:null;\n}\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-063","category":"Segurança e testes","language":"JavaScript","title":"Sanitizar número WhatsApp BR","summary":"Normaliza telefone brasileiro para abrir conversa direta com anunciante.","level":"Intermediário","tags":["whatsapp","anuncios"],"filename":"exemplo.js","code":"function numeroWhatsAppBR(telefone){\n  let numero=String(telefone||'').replace(/\\D/g,'');\n  if([10,11].includes(numero.length))numero='55'+numero;\n  return /^55\\d{10,11}$/.test(numero)?numero:null;\n}\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-064","category":"Segurança e testes","language":"JavaScript","title":"Testes Node nativos","summary":"Testes automatizados sem biblioteca adicional em Node moderno.","level":"Intermediário","tags":["testes","node"],"filename":"exemplo.js","code":"import test from 'node:test';\nimport assert from 'node:assert/strict';\ntest('soma',()=>{assert.equal(2+3,5)});\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-065","category":"Segurança e testes","language":"YAML","title":"GitHub Actions para teste Node","summary":"Fluxo de CI simples para verificar projeto a cada commit.","level":"Intermediário","tags":["github-actions","ci"],"filename":"config.yml","code":"name: Validar projeto\non: [push, pull_request]\njobs:\n  test:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - uses: actions/setup-node@v4\n        with:\n          node-version: '22'\n      - run: npm ci\n      - run: npm test\n","caution":"Requer package-lock.json, scripts npm test e configuração apropriada de permissões."},{"id":"zix-066","category":"Segurança e testes","language":"Bash","title":"Buscar segredos antes de publicar","summary":"Inspeção rápida de possíveis credenciais acidentalmente incluídas no código.","level":"Intermediário","tags":["git","secrets"],"filename":"exemplo.sh","code":"#!/usr/bin/env bash\nset -euo pipefail\n# Revise os resultados: padrões genéricos geram falsos positivos.\ngit grep -nEi '(api[_-]?key|secret|token|password)[[:space:]]*[:=]' -- '*.js' '*.json' '*.env*' || true\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-067","category":"Segurança e testes","language":"Python","title":"Fazer backup SQLite consistente","summary":"API de backup do SQLite com cópia consistente.","level":"Intermediário","tags":["sqlite","backup"],"filename":"exemplo.py","code":"import sqlite3\nwith sqlite3.connect('origem.db') as origem:\n    with sqlite3.connect('copia.db') as destino:\n        origem.backup(destino)\nprint('Backup criado')\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-068","category":"Segurança e testes","language":"SQL","title":"Explicar custo de consulta PostgreSQL","summary":"Consulta estimativa de plano de execução sem alterar registros.","level":"Intermediário","tags":["postgres","performance"],"filename":"consulta.sql","code":"EXPLAIN (FORMAT TEXT)\nSELECT id, created_at FROM public.anuncios_exemplo\nWHERE created_at >= now()-interval '7 days'\nORDER BY created_at DESC LIMIT 50;\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-069","category":"Segurança e testes","language":"JavaScript","title":"Validação de origem de mensagem iframe","summary":"Evita aceitar mensagens cross-origin não autorizadas.","level":"Intermediário","tags":["segurança","iframe"],"filename":"exemplo.js","code":"window.addEventListener('message',event=>{\n  if(event.origin!=='https://app.confiavel.example')return;\n  if(!event.data||event.data.tipo!=='OK')return;\n  console.log('Mensagem autorizada recebida');\n});\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-070","category":"Cinema e multimídia","language":"FFmpeg","title":"Converter vídeo WebM para MP4","summary":"Conversão para MP4 compatível com muitos aparelhos, requer FFmpeg.","level":"Intermediário","tags":["mp4","webm"],"filename":"video.sh","code":"ffmpeg -i entrada.webm -c:v libx264 -preset veryfast -crf 23 -c:a aac -movflags +faststart saida.mp4\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-071","category":"Cinema e multimídia","language":"FFmpeg","title":"Extrair trilha de áudio","summary":"Extrai a trilha de áudio de um vídeo.","level":"Intermediário","tags":["audio","extração"],"filename":"video.sh","code":"ffmpeg -i video.mp4 -vn -c:a libmp3lame -q:a 3 trilha.mp3\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-072","category":"Cinema e multimídia","language":"FFmpeg","title":"Gerar miniatura do vídeo","summary":"Produz imagem de capa a partir do quadro do segundo 3.","level":"Intermediário","tags":["thumbnail","video"],"filename":"video.sh","code":"ffmpeg -ss 00:00:03 -i video.mp4 -frames:v 1 miniatura.jpg\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-073","category":"Cinema e multimídia","language":"FFmpeg","title":"Adicionar legenda SRT ao MP4","summary":"Incorpora legendas no vídeo; requer build FFmpeg com libass.","level":"Intermediário","tags":["legendas","srt"],"filename":"video.sh","code":"ffmpeg -i entrada.mp4 -vf subtitles=legendas.srt -c:a copy com_legendas.mp4\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-074","category":"Cinema e multimídia","language":"FFmpeg","title":"Redimensionar para Full HD","summary":"Redimensiona preservando proporção e preenchendo faixas quando necessário.","level":"Intermediário","tags":["1080p","video"],"filename":"video.sh","code":"ffmpeg -i entrada.mp4 -vf \"scale=1920:1080:force_original_aspect_ratio=decrease,pad=1920:1080:(ow-iw)/2:(oh-ih)/2\" -c:v libx264 -crf 23 -c:a aac fullhd.mp4\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-075","category":"Cinema e multimídia","language":"FFmpeg","title":"Criar vídeo de foto estática","summary":"Transforma foto em cena de sete segundos.","level":"Intermediário","tags":["foto","video"],"filename":"video.sh","code":"ffmpeg -loop 1 -framerate 25 -i foto.jpg -t 7 -c:v libx264 -pix_fmt yuv420p -movflags +faststart cena.mp4\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-076","category":"Cinema e multimídia","language":"Python","title":"Gerar roteiro SRT de legendas","summary":"Gera arquivo de legendas sincronizadas no padrão SubRip.","level":"Intermediário","tags":["srt","roteiro"],"filename":"exemplo.py","code":"from pathlib import Path\ndef srt(legendas):\n    return '\\n'.join(f'{i}\\n{inicio} --> {fim}\\n{texto}\\n' for i,(inicio,fim,texto) in enumerate(legendas,1))\nPath('legendas.srt').write_text(srt([('00:00:00,000','00:00:04,000','Bem-vindo ao ZixLima')]),encoding='utf-8')\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-077","category":"Cinema e multimídia","language":"Python","title":"Planejamento JSON de cenas","summary":"Estrutura de storyboard reutilizável para edição de filmes.","level":"Intermediário","tags":["storyboard","cinema"],"filename":"exemplo.py","code":"import json\ncenas=[{'numero':1,'duracao_segundos':6,'visual':'Nave alienígena sob céu roxo','fala':'A jornada começou.','camera':'plano geral'}]\nwith open('cenas.json','w',encoding='utf-8') as f:json.dump(cenas,f,ensure_ascii=False,indent=2)\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-078","category":"Cinema e multimídia","language":"JavaScript","title":"Gravar canvas em WebM","summary":"Grava imagens de um canvas para arquivo WebM em navegadores compatíveis.","level":"Intermediário","tags":["webm","canvas"],"filename":"exemplo.js","code":"const canvas=document.querySelector('canvas');\nconst stream=canvas.captureStream(25);\nconst mime=['video/webm;codecs=vp9','video/webm'].find(MediaRecorder.isTypeSupported);\nif(!mime)throw Error('Navegador sem suporte WebM');\nconst gravador=new MediaRecorder(stream,{mimeType:mime});\nconst partes=[];gravador.ondataavailable=e=>{if(e.data.size)partes.push(e.data)};\ngravador.onstop=()=>console.log('WebM pronto',new Blob(partes,{type:mime}));\ngravador.start();setTimeout(()=>gravador.stop(),5000);\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-079","category":"Infraestrutura","language":"Docker","title":"Container Python mínimo","summary":"Dockerfile simples com usuário sem privilégios.","level":"Intermediário","tags":["docker","python"],"filename":"Dockerfile","code":"FROM python:3.12-slim\nWORKDIR /app\nCOPY app.py .\nRUN useradd -m appuser\nUSER appuser\nCMD [\"python\",\"app.py\"]\n","caution":"Para serviços reais, fixe digest da imagem, dependências, usuário e políticas de rede."},{"id":"zix-080","category":"Infraestrutura","language":"JSON","title":"package.json de projeto Node","summary":"Base de package.json para verificação automática de código.","level":"Intermediário","tags":["node","npm"],"filename":"config.json","code":"{\"name\":\"exemplo-monstro\",\"private\":true,\"type\":\"module\",\"scripts\":{\"test\":\"node --test\",\"check\":\"node --check src/index.js\"},\"engines\":{\"node\":\">=20\"}}\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-081","category":"Infraestrutura","language":"YAML","title":"GitHub Actions para páginas estáticas","summary":"Modelo mínimo de inspeção de arquivos essenciais do site.","level":"Intermediário","tags":["github","pages"],"filename":"config.yml","code":"name: Verificação estática\non: [push]\njobs:\n  html:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - name: Conferir arquivos\n        run: test -f index.html && test -f app.js\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-082","category":"Infraestrutura","language":"Bash","title":"Ping HTTP de produção","summary":"Verifica status HTTP e latência do site sem alterar dados.","level":"Intermediário","tags":["monitoramento","curl"],"filename":"exemplo.sh","code":"#!/usr/bin/env bash\nset -euo pipefail\nurl=\"${1:-https://example.org}\"\ncurl --fail --silent --show-error --max-time 12 -o /dev/null -w 'HTTP %{http_code} | %{time_total}s\n' \"$url\"\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"zix-083","category":"Infraestrutura","language":"Python","title":"Configuração por variáveis de ambiente","summary":"Mantém credenciais fora dos arquivos distribuídos.","level":"Intermediário","tags":["secrets","deploy"],"filename":"exemplo.py","code":"import os\napi=os.environ.get('MODELO_API_URL','https://example.org/v1/chat/completions')\nchave=os.environ.get('MODELO_API_KEY')\nif not chave:print('Defina MODELO_API_KEY no ambiente')\n","caution":"Adapte caminhos, dependências e credenciais ao seu projeto antes de usar."},{"id":"monstro-zixlima-001-01","title":"GitHub: atualizar sem perder modificações","category":"Termux / Git","language":"Bash","level":"Avançado","summary":"Atualiza a branch main apenas quando a pasta está limpa e a mudança é fast-forward.","filename":"atualizar-git.sh","code":"#!/usr/bin/env bash\nset -euo pipefail\nREPO=\"${1:-$HOME/zixlima}\"\n[[ -d \"$REPO/.git\" ]] || { echo 'Repositório não encontrado'; exit 1; }\ncd \"$REPO\"\nif [[ -n \"$(git status --porcelain)\" ]]; then\n  echo 'Há alterações locais; faça backup ou commit antes de atualizar.'; exit 1\nfi\ngit fetch origin main\ngit merge --ff-only origin/main\necho 'Atualizado sem merge forçado.'\n","tags":["termux","git","segurança"],"caution":"Exemplo educativo sob medida para projetos de desenvolvimento. Revise, adapte, faça backup e teste antes de executar."},{"id":"monstro-zixlima-001-02","title":"Criar backup datado do projeto no Termux","category":"Termux / Backups","language":"Bash","level":"Avançado","summary":"Cópia em arquivo .tar.gz, com exclusões de dependências e arquivos .env.","filename":"backup-projeto.sh","code":"#!/usr/bin/env bash\nset -euo pipefail\nPROJECT=\"${1:-$HOME/zixlima}\"\nDEST=\"$HOME/storage/downloads\"\n[[ -d \"$PROJECT\" && -d \"$DEST\" ]] || { echo 'Verifique caminho do projeto e acesso ao armazenamento'; exit 1; }\nSTAMP=\"$(date +%Y%m%d-%H%M%S)\"\nOUT=\"$DEST/backup-projeto-$STAMP.tar.gz\"\ntar --exclude=.git --exclude=node_modules --exclude=.env --exclude='.env.*' -czf \"$OUT\" -C \"$PROJECT\" .\necho \"Backup criado: $OUT\"\n","tags":["termux","backup"],"caution":"Exemplo educativo sob medida para projetos de desenvolvimento. Revise, adapte, faça backup e teste antes de executar."},{"id":"monstro-zixlima-001-03","title":"Verificar sintaxe antes de publicar","category":"Termux / Qualidade","language":"Bash","level":"Avançado","summary":"Verifica sintaxe de JavaScript, Shell e Python sem executar arquivos do projeto.","filename":"verificar-sintaxe.sh","code":"#!/usr/bin/env bash\nset -euo pipefail\nDIR=\"${1:-.}\"\ncd \"$DIR\"\nif command -v node >/dev/null; then\n  find . -name '*.js' -not -path '*/node_modules/*' -type f -print0 | while IFS= read -r -d '' f; do node --check \"$f\"; done\nfi\nfind . -name '*.sh' -type f -print0 | while IFS= read -r -d '' f; do bash -n \"$f\"; done\nif command -v python >/dev/null; then\n  python - <<'PY_VALIDATE_SCRIPT'\nimport ast,pathlib\nfor p in pathlib.Path('.').rglob('*.py'):\n    if 'node_modules' in p.parts:continue\n    ast.parse(p.read_text(encoding='utf-8'),filename=str(p))\nprint('Python sintaticamente válido')\nPY_VALIDATE_SCRIPT\nfi\necho 'Verificações concluídas.'\n","tags":["node","python","bash"],"caution":"Exemplo educativo sob medida para projetos de desenvolvimento. Revise, adapte, faça backup e teste antes de executar."},{"id":"monstro-zixlima-001-04","title":"Consultar endereço via ViaCEP","category":"Frontend / JavaScript","language":"JavaScript","level":"Avançado","summary":"Busca logradouro e localidade com validação e tratamento de erros.","filename":"consultar-cep.js","code":"async function consultarCEP(cep, signal) {\n  const digits = String(cep).replace(/\\D/g, '');\n  if (!/^\\d{8}$/.test(digits)) throw new Error('CEP deve ter 8 dígitos');\n  const res = await fetch(`https://viacep.com.br/ws/${digits}/json/`, {signal});\n  if (!res.ok) throw new Error('Serviço de CEP indisponível');\n  const d = await res.json();\n  if (d.erro) throw new Error('CEP não encontrado');\n  return {rua:d.logradouro||'', bairro:d.bairro||'', cidade:d.localidade||'', uf:d.uf||''};\n}\n// Mantenha campos editáveis e peça autorização antes de publicar endereço completo.\n","tags":["cep","cadastro","viaCEP"],"caution":"Exemplo educativo sob medida para projetos de desenvolvimento. Revise, adapte, faça backup e teste antes de executar."},{"id":"monstro-zixlima-001-05","title":"Modelo de controle de acesso RLS Supabase","category":"Supabase / SQL","language":"SQL","level":"Avançado","summary":"Exemplo de políticas que limitam acesso ao proprietário do registro.","filename":"rls-modelo.sql","code":"-- MODELO: exige uma tabela fictícia public.meus_documentos(owner_id uuid, ...).\n-- NÃO aplique diretamente sobre tabelas existentes sem analisar as políticas atuais.\nALTER TABLE public.meus_documentos ENABLE ROW LEVEL SECURITY;\nCREATE POLICY meus_docs_ler ON public.meus_documentos\n  FOR SELECT TO authenticated USING (owner_id = (SELECT auth.uid()));\nCREATE POLICY meus_docs_criar ON public.meus_documentos\n  FOR INSERT TO authenticated WITH CHECK (owner_id = (SELECT auth.uid()));\nCREATE POLICY meus_docs_editar ON public.meus_documentos\n  FOR UPDATE TO authenticated USING (owner_id = (SELECT auth.uid()))\n  WITH CHECK (owner_id = (SELECT auth.uid()));\n","tags":["supabase","rls","privacidade"],"caution":"Exemplo educativo sob medida para projetos de desenvolvimento. Revise, adapte, faça backup e teste antes de executar."},{"id":"monstro-zixlima-001-06","title":"Fazer backup transacional de SQLite","category":"Banco de dados / Python","language":"Python","level":"Avançado","summary":"Copia um banco SQLite consistentemente, sem interromper operações do aplicativo.","filename":"backup-sqlite.py","code":"import sqlite3\nfrom pathlib import Path\nfrom datetime import datetime\n\ndef salvar_copia(origem, pasta):\n    origem=Path(origem)\n    destino_dir=Path(pasta)\n    if not origem.is_file(): raise FileNotFoundError(origem)\n    destino_dir.mkdir(parents=True,exist_ok=True)\n    destino=destino_dir/f'backup-{datetime.now():%Y%m%d-%H%M%S}.sqlite3'\n    if destino.exists(): raise FileExistsError(destino)\n    with sqlite3.connect(origem) as db, sqlite3.connect(destino) as backup:\n        db.backup(backup)\n    return destino\n","tags":["python","sqlite","backup"],"caution":"Exemplo educativo sob medida para projetos de desenvolvimento. Revise, adapte, faça backup e teste antes de executar."},{"id":"monstro-zixlima-001-07","title":"Exibir anúncios sem interpretar HTML de usuários","category":"Segurança / JavaScript","language":"JavaScript","level":"Avançado","summary":"Evita executar marcação maliciosa presente em conteúdo de anúncios.","filename":"anuncio-seguro.js","code":"function mostrarAnuncio(container, anuncio) {\n  const artigo = document.createElement('article');\n  const titulo = document.createElement('h3');\n  const descricao = document.createElement('p');\n  titulo.textContent = String(anuncio.title || 'Sem título');\n  descricao.textContent = String(anuncio.description || '');\n  artigo.append(titulo,descricao);\n  container.replaceChildren(artigo);\n}\n","tags":["xss","javascript","classificados"],"caution":"Exemplo educativo sob medida para projetos de desenvolvimento. Revise, adapte, faça backup e teste antes de executar."},{"id":"monstro-zixlima-001-08","title":"Transformar vídeo WebM em MP4 pelo Termux","category":"Cinema / FFmpeg","language":"Bash","level":"Avançado","summary":"Converte vídeos gerados no navegador sem substituir o arquivo original.","filename":"converter-mp4.sh","code":"#!/usr/bin/env bash\nset -euo pipefail\n[[ $# -eq 1 && -f \"$1\" ]] || { echo 'Uso: bash converter.sh filme.webm'; exit 1; }\ncommand -v ffmpeg >/dev/null || { echo 'Instale o FFmpeg: pkg install ffmpeg'; exit 1; }\nORIGEM=\"$1\"; SAIDA=\"${ORIGEM%.*}.mp4\"\n[[ ! -e \"$SAIDA\" ]] || { echo 'Arquivo de destino já existe; não vou substituir.'; exit 1; }\nffmpeg -nostdin -i \"$ORIGEM\" -c:v libx264 -pix_fmt yuv420p -c:a aac -movflags +faststart \"$SAIDA\"\necho \"Salvo: $SAIDA\"\n","tags":["video","termux","ffmpeg"],"caution":"Exemplo educativo sob medida para projetos de desenvolvimento. Revise, adapte, faça backup e teste antes de executar."},{"id":"monstro-zixlima-001-09","title":"Servidor local Python sem abrir acesso à rede","category":"Backend / Python","language":"Python","level":"Avançado","summary":"Servidor de desenvolvimento que escuta apenas o dispositivo atual.","filename":"servidor-local.py","code":"from http.server import ThreadingHTTPServer, SimpleHTTPRequestHandler\nfrom pathlib import Path\nROOT=Path(__file__).resolve().parent\nclass LocalHandler(SimpleHTTPRequestHandler):\n    def __init__(self,*args,**kwargs):\n        super().__init__(*args,directory=str(ROOT),**kwargs)\nprint('Abra: http://127.0.0.1:8765')\nThreadingHTTPServer(('127.0.0.1',8765),LocalHandler).serve_forever()\n","tags":["localhost","python"],"caution":"Exemplo educativo sob medida para projetos de desenvolvimento. Revise, adapte, faça backup e teste antes de executar."},{"id":"monstro-zixlima-001-10","title":"Examinar alterações Git sem publicar nada","category":"Termux / Git","language":"Bash","level":"Avançado","summary":"Inspeciona o que será publicado e não executa alterações remotas.","filename":"auditar-git.sh","code":"#!/usr/bin/env bash\nset -euo pipefail\ncd \"${1:-$HOME/zixlima}\"\ngit rev-parse --is-inside-work-tree >/dev/null\nprintf '\\nArquivos alterados:\\n'; git status --short\nprintf '\\nResumo das mudanças:\\n'; git diff --stat\nprintf '\\nProblemas de espaçamento:\\n'; git diff --check\necho 'Somente auditoria: não houve commit ou push.'\n","tags":["github","segurança","auditoria"],"caution":"Exemplo educativo sob medida para projetos de desenvolvimento. Revise, adapte, faça backup e teste antes de executar."}]};
